--#############################
--## WINDOWS AND WORKSPACES ###
--#############################

-- See https://wiki.hypr.land/Configuring/Window-Rules/ for more
-- See https://wiki.hypr.land/Configuring/Workspace-Rules/ for workspace rules

-- Example windowrule
-- windowrule = float,class:^(kitty)$,title:^(kitty)$

-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.window_rule({
    match = {
        title = "(.*)(Zen Browser Private Browsing)",
    },
    no_screen_share = true,
})

-- Floating Windows and Window Size
hl.window_rule({
    match = {
        class = "^(steam)$",
        title = "negative:^(Steam)$",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "^(waypaper)$",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "^(com.saivert.pwvucontrol)$",
    },
    float = true,
    size = "949 820",
})

hl.window_rule({
    match = {
        class = "^(mpv)$",
    },
    fullscreen = true,
})

-- Start on specific monitor
hl.window_rule({
    match = {
        class = "^(Edmarketconnector)$",
    },
    monitor = "DP-1",
})

hl.window_rule({
    match = {
        class = "^(discord)$",
    },
    monitor = "DP-1",
})

-- Ignore maximize requests from apps. You'll probably like this.
hl.window_rule({
    match = {
        class = ".*",
    },
    suppress_event = "maximize",
})

-- Fix some dragging issues with XWayland
hl.window_rule({
    match = {
        class = "^$",
        title = "^$",
        xwayland = 1,
        float = 1,
        fullscreen = 0,
        pin = 0,
    },
    no_focus = true,
})

-- Binding monitor to workspace
hl.workspace_rule({
    workspace = "1",
    monitor = "DP-2",
    default = true,
})

hl.workspace_rule({
    workspace = "2",
    monitor = "DP-2",
})

hl.workspace_rule({
    workspace = "3",
    monitor = "DP-2",
})

hl.workspace_rule({
    workspace = "4",
    monitor = "DP-2",
})

hl.workspace_rule({
    workspace = "5",
    monitor = "DP-2",
})

hl.workspace_rule({
    workspace = "6",
    monitor = "DP-1",
    default = true,
})

hl.workspace_rule({
    workspace = "7",
    monitor = "DP-1",
})

hl.workspace_rule({
    workspace = "8",
    monitor = "DP-1",
})

hl.workspace_rule({
    workspace = "9",
    monitor = "DP-1",
})

hl.workspace_rule({
    workspace = "10",
    monitor = "DP-1",
})

